 * MyActuator ESP32 Firmware - Common Type Definitions
 * 
 * Defines core types, enums, and constants used across all motor series
 * and protocol implementations.
 */

#pragma once

#include <stdint.h>
#include <stdbool.h>

// ============================================================================
// Protocol Types
// ============================================================================

typedef enum {
    PROTOCOL_CAN = 0,
    PROTOCOL_RS485,
    PROTOCOL_ETHERCAT,
    PROTOCOL_COUNT
} ProtocolType;

// ============================================================================
// Motor Series Types
// ============================================================================

typedef enum {
    MOTOR_RMD_X = 0,  // Planetary
    MOTOR_RH,         // Harmonic
    MOTOR_CEM,        // Cycloid
    MOTOR_RMD_H,      // Direct Drive Hollow
    MOTOR_RMD_L,      // Direct Drive
    MOTOR_FL,         // Linear
    MOTOR_COUNT
} MotorSeries;

// ============================================================================
// Frame Types (from PROTOCOLS_CONTRACT.md)
// ============================================================================

typedef enum {
    STATUS_REPORT = 0x00,
    POSITION_CMD = 0x01,
    TORQUE_CMD = 0x02,
    VELOCITY_CMD = 0x03,
    HOME_CMD = 0x04,
    PARAM_READ = 0x05,
    PARAM_WRITE = 0x06,
    FAULT_RESET = 0x07,
    FIRMWARE_UPDATE = 0x08,
    RESERVED = 0x0A - 0xFF
} FrameType;

// ============================================================================
// Status Word Bit Definitions (from MOTOR_RMD_X_CONTRACT.md)
// ============================================================================

typedef struct {
    uint16_t ready : 1;
    uint16_t enabled : 1;
    uint16_t fault : 1;
    uint16_t homed : 1;
    uint16_t reserved : 12;
} StatusWord;

// ============================================================================
// Motor Configuration (from ESP32_FIRMWARE_CONTRACT.md)
// ============================================================================

typedef struct {
    MotorSeries series;
    uint8_t motor_id;
    ProtocolType protocol;
    uint32_t max_current_mA;
    uint16_t max_velocity_rpm;
    uint16_t reduction_ratio;
    uint8_t encoder_bits;
    bool has_brake;
    bool has_encoder;
} MotorConfig;

// ============================================================================
// CAN Bus Configuration (from PROTOCOLS_CONTRACT.md)
// ============================================================================

typedef struct {
    uint32_t bitrate;           // 500000 for 500kbps
    uint8_t id;                 // Motor ID (0-127)
    bool use_extended_id;       // 29-bit vs 11-bit
} CANConfig;

// ============================================================================
// RS485 Configuration (from PROTOCOLS_CONTRACT.md)
// ============================================================================

typedef struct {
    uint32_t baudrate;          // 115200
    uint8_t address;            // Modbus address
    uint8_t timeout_ms;         // Response timeout
} RS485Config;

// ============================================================================
// EtherCAT Configuration (from PROTOCOLS_CONTRACT.md)
// ============================================================================

typedef struct {
    uint8_t node_id;
    uint16_t cycle_time_us;     // 1000us = 1ms
    uint8_t alias;
    uint16_t position;
} EtherCATConfig;

// ============================================================================
// Fault Codes (from ESP32_FIRMWARE_CONTRACT.md)
// ============================================================================

typedef enum {
    FAULT_NONE = 0,
    FAULT_OVERTEMPERATURE,
    FAULT_OVERCURRENT,
    FAULT_UNDERVOLTAGE,
    FAULT_OVERSPEED,
    FAULT_ENCODER,
    FAULT_COMMUNICATION,
    FAULT_MOTOR,
    FAULT_COUNT
} FaultCode;

// ============================================================================
// Control Modes
// ============================================================================

typedef enum {
    CONTROL_POSITION = 0,
    CONTROL_VELOCITY,
    CONTROL_TORQUE,
    CONTROL_HOMING
} ControlMode;

// ============================================================================
// Logging Levels (from ESP32_FIRMWARE_CONTRACT.md)
// ============================================================================

typedef enum {
    LOG_LEVEL_ERROR = 0,
    LOG_LEVEL_WARN,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_VERBOSE
} LogLevel;

// ============================================================================
// Constants
// ============================================================================

#define MAX_MOTORS 8
#define MAX_FRAME_SIZE 64
#define DEFAULT_BITRATE 500000
#define DEFAULT_BAUDRATE 115200
#define DEFAULT_CYCLE_TIME_US 1000
#define CONTROL_LOOP_PERIOD_US 1000  // 1ms
"}

